// GENERATED by scripts/gen-arch-presets.ts from src/arch/presets/*.jsonc: edit those, then run
// `npx tsx scripts/gen-arch-presets.ts`. The shipped presets (`mapx:preset/<id>`, M5-17), as JSONC text.
export const PRESET_TEXTS: Readonly<Record<string, string>> = {
  "aspnet": "// mapx:preset/aspnet: an ASP.NET Core application (MVC, Web API, Razor Pages).\n// AR-15 (M5-17-R1). By ASP.NET's folder conventions, and by the framework base classes wherever a\n// class lives: ControllerBase and Controller (both named, since a base outside the workspace is a\n// leaf), PageModel, and Entity Framework's DbContext. Controllers and pages may inject the DbContext,\n// as the scaffolded ones do; models and DTOs depend on no layer above them.\n// No parameters: the folder names place every file, in whichever project it is.\n{\n  \"layers\": [\n    // MVC and API controllers.\n    { \"name\": \"Controllers\", \"selectors\": [\n      { \"path\": \"**/Controllers/**\" },\n      { \"inherits\": \"ControllerBase\" },\n      { \"inherits\": \"Controller\" },\n      { \"decorator\": \"ApiController\", \"members\": true }\n    ] },\n    // Razor Pages page models.\n    { \"name\": \"Pages\", \"selectors\": [{ \"path\": \"**/Pages/**\" }, { \"inherits\": \"PageModel\" }] },\n    // Middleware classes.\n    { \"name\": \"Middleware\", \"selectors\": [{ \"path\": \"**/Middleware/**\" }] },\n    // Application services.\n    { \"name\": \"Services\", \"selectors\": [{ \"path\": \"**/Services/**\" }] },\n    // Data access: DbContexts (any DbContext subclass), repositories and migrations.\n    { \"name\": \"Data\", \"selectors\": [{ \"path\": \"**/{Data,Repositories,Migrations}/**\" }, { \"inherits\": \"DbContext\" }] },\n    // Request and response types, and MVC view models.\n    { \"name\": \"Dtos\", \"selectors\": [{ \"path\": \"**/{Dtos,DTOs,Contracts,ViewModels}/**\" }] },\n    // Domain and persistence models.\n    { \"name\": \"Models\", \"selectors\": [{ \"path\": \"**/{Models,Entities,Domain}/**\" }] }\n  ],\n  \"rules\": {\n    \"Controllers\": [\"Services\", \"Data\", \"Dtos\", \"Models\"],\n    \"Pages\": [\"Services\", \"Data\", \"Dtos\", \"Models\"],\n    \"Middleware\": [\"Services\"],\n    \"Services\": [\"Data\", \"Dtos\", \"Models\"],\n    \"Data\": [\"Models\"],\n    \"Dtos\": [\"Models\"],\n    \"Models\": []\n  }\n}\n",
  "clean": "// mapx:preset/clean: Clean Architecture, dependencies pointing inward.\n// AR-15. Infrastructure → Adapters → Application → Domain; the Domain depends on nothing (builtins aside).\n// Parameter: root, the folder holding the layer folders (\"src/\" by default, \"\" for the repo root).\n{\n  \"parameters\": { \"root\": \"src/\" },\n  \"layers\": [\n    // Enterprise rules: entities and value objects.\n    { \"name\": \"Domain\", \"selectors\": [{ \"path\": \"%root%{domain,entities,entity}/**\" }] },\n    // Application rules: use cases and the ports they need.\n    { \"name\": \"Application\", \"selectors\": [{ \"path\": \"%root%{application,usecases,use-cases,use_cases}/**\" }] },\n    // Interface adapters: controllers, presenters, gateways.\n    { \"name\": \"Adapters\", \"selectors\": [{ \"path\": \"%root%{adapters,interface-adapters,controllers,controller,presenters,gateways,presentation,interfaces,api,web,ui}/**\" }] },\n    // Frameworks and drivers: the database, external services, the web framework.\n    { \"name\": \"Infrastructure\", \"selectors\": [{ \"path\": \"%root%{infrastructure,infra,frameworks,drivers,persistence,db,database,external}/**\" }] }\n  ],\n  \"rules\": {\n    \"Infrastructure\": [\"Adapters\", \"Application\", \"Domain\"],\n    \"Adapters\": [\"Application\", \"Domain\"],\n    \"Application\": [\"Domain\"],\n    \"Domain\": []\n  }\n}\n",
  "ddd-contexts": "// mapx:preset/ddd-contexts: bounded contexts that share only a kernel.\n// AR-15. Each context is one layer, declared by the configuration that extends this preset\n// (`mapx arch init --preset ddd-contexts` adds one per folder under root), for example { \"name\": \"Billing\", \"selectors\": [{ \"path\": \"%root%billing/**\" }] }.\n// A context may depend on the SharedKernel and on nothing else: never on another context.\n// Parameter: root, the folder holding the context folders (\"src/\" by default, \"\" for the repo root).\n{\n  \"parameters\": { \"root\": \"src/\" },\n  \"layers\": [\n    // Code every context shares.\n    { \"name\": \"SharedKernel\", \"selectors\": [{ \"path\": \"%root%{shared,shared-kernel,shared_kernel,sharedkernel,kernel,common}/**\" }] }\n  ],\n  \"rules\": {\n    // A default for every layer, contexts included.\n    \"*\": [\"SharedKernel\"],\n    \"SharedKernel\": []\n  }\n}\n",
  "django": "// mapx:preset/django: a Django project.\n// AR-15. By Django's module-name conventions, in every app, and by the framework's base classes\n// (M5-17-R1): a class that extends models.Model, or a Django or REST framework view, is placed by its\n// ancestry in whichever module it is; the module names stay the fallback for everything else.\n// Models never depend on views, forms or serializers; URLconfs reach views only.\n// No parameters: the module names place every file, in whichever app it is.\n{\n  \"layers\": [\n    // URLconfs.\n    { \"name\": \"Urls\", \"selectors\": [{ \"path\": \"**/urls.py\" }] },\n    // Views and viewsets: by module, and any class-based view (django.views, the REST framework's\n    // views, generics and viewsets).\n    { \"name\": \"Views\", \"selectors\": [\n      { \"path\": \"**/{views,viewsets}.py\" },\n      { \"path\": \"**/views/**\" },\n      { \"inherits\": \"/^(django\\\\.views|rest_framework\\\\.(views|generics|viewsets))\\\\./\" }\n    ] },\n    // The admin site.\n    { \"name\": \"Admin\", \"selectors\": [{ \"path\": \"**/admin.py\" }] },\n    // Management commands.\n    { \"name\": \"Commands\", \"selectors\": [{ \"path\": \"**/management/commands/**\" }] },\n    // Forms and REST framework serializers.\n    { \"name\": \"Forms\", \"selectors\": [{ \"path\": \"**/forms.py\" }, { \"path\": \"**/forms/**\" }] },\n    { \"name\": \"Serializers\", \"selectors\": [{ \"path\": \"**/serializers.py\" }, { \"path\": \"**/serializers/**\" }] },\n    // Schema migrations. They use historical models (apps.get_model), never the current ones, as\n    // Django's docs require: a migration importing a model is a violation (M5-17-R1).\n    { \"name\": \"Migrations\", \"selectors\": [{ \"path\": \"**/migrations/**\" }] },\n    // Models: by module, and any class that extends django.db.models.Model.\n    { \"name\": \"Models\", \"selectors\": [{ \"path\": \"**/models.py\" }, { \"path\": \"**/models/**\" }, { \"extends\": \"django.db.models.Model\" }] }\n  ],\n  \"rules\": {\n    \"Urls\": [\"Views\"],\n    \"Views\": [\"Forms\", \"Serializers\", \"Models\"],\n    \"Admin\": [\"Forms\", \"Models\"],\n    \"Commands\": [\"Models\"],\n    \"Forms\": [\"Models\"],\n    \"Serializers\": [\"Models\"],\n    \"Migrations\": [],\n    \"Models\": []\n  }\n}\n",
  "express": "// mapx:preset/express: an Express application (routes, controllers, services, models).\n// AR-15 (M5-17-R1). By the folder layout most Express apps and generators use. Routes reach the\n// domain only through controllers; models depend on configuration only.\n// Parameter: root, the folder holding the layer folders (\"src/\" by default, \"\" for the repo root).\n{\n  \"parameters\": { \"root\": \"src/\" },\n  \"layers\": [\n    // The application and server setup.\n    { \"name\": \"App\", \"selectors\": [{ \"path\": \"%root%{app,server,index}.{js,ts,mjs,cjs}\" }] },\n    // Routers: they map paths to controllers and middleware.\n    { \"name\": \"Routes\", \"selectors\": [{ \"path\": \"%root%{routes,routers,router}/**\" }] },\n    // Request handlers.\n    { \"name\": \"Controllers\", \"selectors\": [{ \"path\": \"%root%{controllers,controller,handlers}/**\" }] },\n    // Middleware: authentication, validation, error handling.\n    { \"name\": \"Middleware\", \"selectors\": [{ \"path\": \"%root%{middleware,middlewares}/**\" }] },\n    // Business logic.\n    { \"name\": \"Services\", \"selectors\": [{ \"path\": \"%root%{services,service}/**\" }] },\n    // Data models and schemas (Mongoose, Sequelize, plain classes).\n    { \"name\": \"Models\", \"selectors\": [{ \"path\": \"%root%{models,model}/**\" }] },\n    // Settings every layer may read.\n    { \"name\": \"Config\", \"selectors\": [{ \"path\": \"%root%{config,configs}/**\" }] }\n  ],\n  \"rules\": {\n    \"App\": [\"Routes\", \"Middleware\", \"Config\"],\n    \"Routes\": [\"Controllers\", \"Middleware\"],\n    \"Controllers\": [\"Services\", \"Config\"],\n    \"Middleware\": [\"Services\", \"Config\"],\n    \"Services\": [\"Models\", \"Config\"],\n    \"Models\": [\"Config\"],\n    \"Config\": []\n  }\n}\n",
  "fastapi": "// mapx:preset/fastapi: a FastAPI application.\n// AR-15 (M5-17-R1). By the layouts of FastAPI's own guides: the full-stack template (api/routes,\n// api/deps.py, core/, crud.py, models.py) and the SQL tutorial (routers/, dependencies.py,\n// database.py, crud.py, models.py, schemas.py). Path operations may use the models directly (the\n// template's SQLModel classes are its schemas too); core may seed the database through crud and the\n// models (init_db); schemas and the models depend on no layer above them.\n// Parameter: root, the application package (\"app/\" by default, \"\" for the repo root).\n{\n  \"parameters\": { \"root\": \"app/\" },\n  \"layers\": [\n    // The application object: main.py.\n    { \"name\": \"App\", \"selectors\": [{ \"path\": \"%root%main.py\" }] },\n    // Path operations: APIRouter modules (api/ but its dependencies).\n    { \"name\": \"Routers\", \"selectors\": [{ \"all\": [\n      { \"path\": \"%root%{routers,routes,endpoints,api}/**\" },\n      { \"not\": { \"path\": \"%root%**/{dependencies,deps}{.py,/**}\" } }\n    ] }] },\n    // Dependencies (Depends providers): sessions, the current user; deps.py anywhere in the package.\n    { \"name\": \"Dependencies\", \"selectors\": [{ \"path\": \"%root%**/{dependencies,deps}.py\" }, { \"path\": \"%root%**/{dependencies,deps}/**\" }] },\n    // Business logic and CRUD helpers.\n    { \"name\": \"Services\", \"selectors\": [{ \"path\": \"%root%{services,crud}/**\" }, { \"path\": \"%root%{services,crud}.py\" }] },\n    // Pydantic request and response schemas.\n    { \"name\": \"Schemas\", \"selectors\": [{ \"path\": \"%root%schemas/**\" }, { \"path\": \"%root%schemas.py\" }] },\n    // ORM models (SQLAlchemy, SQLModel).\n    { \"name\": \"Models\", \"selectors\": [{ \"path\": \"%root%models/**\" }, { \"path\": \"%root%models.py\" }] },\n    // Settings, the database engine and session, security helpers.\n    { \"name\": \"Core\", \"selectors\": [{ \"path\": \"%root%{core,db}/**\" }, { \"path\": \"%root%{config,database,db,settings,security}.py\" }] }\n  ],\n  \"rules\": {\n    \"App\": [\"Routers\", \"Dependencies\", \"Services\", \"Schemas\", \"Models\", \"Core\"],\n    \"Routers\": [\"Dependencies\", \"Services\", \"Schemas\", \"Models\", \"Core\"],\n    \"Dependencies\": [\"Services\", \"Schemas\", \"Models\", \"Core\"],\n    \"Services\": [\"Schemas\", \"Models\", \"Core\"],\n    \"Core\": [\"Services\", \"Models\"],\n    \"Models\": [\"Core\"],\n    \"Schemas\": []\n  }\n}\n",
  "feature-sliced": "// mapx:preset/feature-sliced: Feature-Sliced Design for frontends.\n// AR-15. Strict top-down order: a layer may depend on every layer below it, never on one above.\n// (FSD's other rule, no imports between slices of one layer, needs a layer per slice: declare\n// those to enforce it.)\n// Parameter: root, the folder holding the layer folders (\"src/\" by default, \"\" for the repo root).\n{\n  \"parameters\": { \"root\": \"src/\" },\n  \"layers\": [\n    // Application setup: providers, routing, global styles.\n    { \"name\": \"App\", \"selectors\": [{ \"path\": \"%root%app/**\" }] },\n    // Complex scenarios across pages (deprecated in FSD 2, kept for older code).\n    { \"name\": \"Processes\", \"selectors\": [{ \"path\": \"%root%processes/**\" }] },\n    // Full pages.\n    { \"name\": \"Pages\", \"selectors\": [{ \"path\": \"%root%pages/**\" }] },\n    // Self-contained blocks of a page.\n    { \"name\": \"Widgets\", \"selectors\": [{ \"path\": \"%root%widgets/**\" }] },\n    // User interactions that bring business value.\n    { \"name\": \"Features\", \"selectors\": [{ \"path\": \"%root%features/**\" }] },\n    // Business entities.\n    { \"name\": \"Entities\", \"selectors\": [{ \"path\": \"%root%entities/**\" }] },\n    // Reusable code with no business logic: UI kit, helpers, API client.\n    { \"name\": \"Shared\", \"selectors\": [{ \"path\": \"%root%shared/**\" }] }\n  ],\n  \"rules\": {\n    \"App\": [\"Processes\", \"Pages\", \"Widgets\", \"Features\", \"Entities\", \"Shared\"],\n    \"Processes\": [\"Pages\", \"Widgets\", \"Features\", \"Entities\", \"Shared\"],\n    \"Pages\": [\"Widgets\", \"Features\", \"Entities\", \"Shared\"],\n    \"Widgets\": [\"Features\", \"Entities\", \"Shared\"],\n    \"Features\": [\"Entities\", \"Shared\"],\n    \"Entities\": [\"Shared\"],\n    \"Shared\": []\n  }\n}\n",
  "flutter": "// mapx:preset/flutter: a Flutter application.\n// AR-15 (M5-17-R1). By the usual lib/ folders, and by the state-management base classes wherever a\n// class lives (ChangeNotifier, ValueNotifier, Bloc, Cubit, Riverpod's notifiers). Screens and\n// widgets reach services only through their state; models depend on nothing.\n// Parameter: root, the folder holding the Dart sources (\"lib/\" by default).\n{\n  \"parameters\": { \"root\": \"lib/\" },\n  \"layers\": [\n    // The entry point and the app widget.\n    { \"name\": \"App\", \"selectors\": [{ \"path\": \"%root%{main,app}.dart\" }] },\n    // Full screens (routes).\n    { \"name\": \"Screens\", \"selectors\": [{ \"path\": \"%root%{screens,pages,views}/**\" }] },\n    // Reusable widgets.\n    { \"name\": \"Widgets\", \"selectors\": [{ \"path\": \"%root%{widgets,components}/**\" }] },\n    // State management: notifiers, blocs, cubits, providers, controllers.\n    { \"name\": \"State\", \"selectors\": [\n      { \"path\": \"%root%{state,providers,blocs,bloc,cubits,notifiers,controllers,viewmodels}/**\" },\n      { \"inherits\": \"/(^|\\\\.)(ChangeNotifier|ValueNotifier|Bloc|Cubit|StateNotifier|Notifier|AsyncNotifier)$/\" }\n    ] },\n    // Services, repositories and API clients.\n    { \"name\": \"Services\", \"selectors\": [{ \"path\": \"%root%{services,repositories,data,api}/**\" }] },\n    // Plain data models.\n    { \"name\": \"Models\", \"selectors\": [{ \"path\": \"%root%{models,domain,entities}/**\" }] }\n  ],\n  \"rules\": {\n    \"App\": [\"Screens\", \"Widgets\", \"State\", \"Services\"],\n    \"Screens\": [\"Widgets\", \"State\", \"Models\"],\n    \"Widgets\": [\"State\", \"Models\"],\n    \"State\": [\"Services\", \"Models\"],\n    \"Services\": [\"Models\"],\n    \"Models\": []\n  }\n}\n",
  "hexagonal": "// mapx:preset/hexagonal: ports and adapters.\n// AR-15. Adapters plug into the application's ports; the application drives the domain; the domain\n// depends on nothing (builtins aside).\n// Parameter: root, the folder holding the layer folders (\"src/\" by default, \"\" for the repo root).\n{\n  \"parameters\": { \"root\": \"src/\" },\n  \"layers\": [\n    // The model and its rules.\n    { \"name\": \"Domain\", \"selectors\": [{ \"path\": \"%root%{domain,model,core}/**\" }] },\n    // Use cases and the ports (interfaces) adapters implement or call.\n    { \"name\": \"Application\", \"selectors\": [{ \"path\": \"%root%{application,ports,port,usecases,use-cases}/**\" }] },\n    // Driving and driven adapters: HTTP, CLI, persistence, messaging.\n    { \"name\": \"Adapters\", \"selectors\": [{ \"path\": \"%root%{adapters,adapter,infrastructure,infra}/**\" }] }\n  ],\n  \"rules\": {\n    \"Adapters\": [\"Application\", \"Domain\"],\n    \"Application\": [\"Domain\"],\n    \"Domain\": []\n  }\n}\n",
  "laravel": "// mapx:preset/laravel: a Laravel application.\n// AR-15. By Laravel's folder conventions, the framework parts MapX detects (route handlers,\n// middleware, Eloquent models with relations) and the framework's base types (M5-17-R1): a class\n// that extends Eloquent's Model, implements ShouldQueue or extends a controller base is placed by\n// its ancestry wherever it lives, and the folders stay the fallback for classes without one. Idiomatic Laravel 11 passes it: route closures with\n// route-model binding, invokable actions routed directly, the scheduler in routes/console.php,\n// listeners that type-hint their event, a model dispatching a job from booted(), the default User\n// model naming its factory. Models never depend on Http; Jobs, Listeners and Providers never on Http\n// either.\n// Parameter: root, the folder holding the application (\"\" when artisan is at the repo root).\n{\n  \"parameters\": { \"root\": \"\" },\n  \"layers\": [\n    // Route files (web, api, channels): they name controllers or invokable actions, and their\n    // closures bind models. routes/console.php is the scheduler: it is in Console.\n    { \"name\": \"Routes\", \"selectors\": [{ \"all\": [{ \"path\": \"%root%routes/**\" }, { \"not\": { \"path\": \"%root%routes/console.php\" } }] }] },\n    // Controllers, middleware, form requests and resources, and any other class a route or\n    // middleware edge targets (module controllers). Route files, whose closures are route handlers\n    // too, stay in Routes, and routed actions stay in Services. A class extending a controller base\n    // (the app's Controller, or Illuminate's before Laravel 11) is in Http wherever it is.\n    { \"name\": \"Http\", \"selectors\": [\n      { \"path\": \"%root%app/Http/**\" },\n      { \"extends\": \"App\\\\Http\\\\Controllers\\\\Controller\" },\n      { \"extends\": \"Illuminate\\\\Routing\\\\Controller\" },\n      { \"all\": [{ \"framework\": \"route-handler\" }, { \"not\": { \"any\": [{ \"path\": \"%root%routes/**\" }, { \"path\": \"%root%app/{Services,Actions,Domain}/**\" }] } }] },\n      { \"framework\": \"middleware\" }\n    ] },\n    // Artisan commands, and the schedule and closure commands of routes/console.php.\n    { \"name\": \"Console\", \"selectors\": [{ \"path\": \"%root%app/Console/**\" }, { \"path\": \"%root%routes/console.php\" }] },\n    // Service providers: the container's wiring.\n    { \"name\": \"Providers\", \"selectors\": [{ \"path\": \"%root%app/Providers/**\" }] },\n    // Jobs, and any class that implements ShouldQueue outside the folders whose classes queue for\n    // their own reasons (queued listeners, mail and notifications).\n    { \"name\": \"Jobs\", \"selectors\": [\n      { \"path\": \"%root%app/Jobs/**\" },\n      { \"all\": [{ \"implements\": \"Illuminate\\\\Contracts\\\\Queue\\\\ShouldQueue\" }, { \"not\": { \"path\": \"%root%app/{Listeners,Mail,Notifications}/**\" } }] }\n    ] },\n    // Events and their listeners.\n    { \"name\": \"Events\", \"selectors\": [{ \"path\": \"%root%app/Events/**\" }] },\n    { \"name\": \"Listeners\", \"selectors\": [{ \"path\": \"%root%app/Listeners/**\" }] },\n    // Domain logic outside the framework: services, actions (invokable ones may be routed), a domain\n    // folder. An Eloquent model there is in Models only.\n    { \"name\": \"Services\", \"selectors\": [{ \"all\": [\n      { \"path\": \"%root%app/{Services,Actions,Domain}/**\" },\n      { \"not\": { \"any\": [\n        { \"extends\": \"Illuminate\\\\Database\\\\Eloquent\\\\Model\" },\n        { \"extends\": \"Illuminate\\\\Foundation\\\\Auth\\\\User\" },\n        { \"extends\": \"Illuminate\\\\Database\\\\Eloquent\\\\Relations\\\\Pivot\" }\n      ] } }\n    ] }] },\n    // Eloquent models: by folder, by ancestry (Model, the Authenticatable user, Pivot), and any class\n    // with relation edges.\n    { \"name\": \"Models\", \"selectors\": [\n      { \"path\": \"%root%app/Models/**\" },\n      { \"extends\": \"Illuminate\\\\Database\\\\Eloquent\\\\Model\" },\n      { \"extends\": \"Illuminate\\\\Foundation\\\\Auth\\\\User\" },\n      { \"extends\": \"Illuminate\\\\Database\\\\Eloquent\\\\Relations\\\\Pivot\" },\n      { \"framework\": \"model\" }\n    ] },\n    // Blade views.\n    { \"name\": \"Views\", \"selectors\": [{ \"path\": \"%root%resources/views/**\" }] },\n    // Migrations, factories and seeders.\n    { \"name\": \"Database\", \"selectors\": [{ \"path\": \"%root%database/**\" }] }\n  ],\n  \"rules\": {\n    \"Routes\": [\"Http\", \"Services\", \"Models\"],\n    \"Http\": [\"Services\", \"Models\", \"Jobs\", \"Events\", \"Views\"],\n    \"Console\": [\"Services\", \"Models\", \"Jobs\", \"Events\"],\n    \"Providers\": [\"Services\", \"Models\", \"Jobs\", \"Events\", \"Listeners\"],\n    \"Jobs\": [\"Services\", \"Models\", \"Events\"],\n    \"Listeners\": [\"Events\", \"Services\", \"Models\", \"Jobs\"],\n    \"Events\": [\"Models\"],\n    \"Services\": [\"Models\", \"Jobs\", \"Events\"],\n    \"Models\": [\"Events\", \"Jobs\", \"Database\"],\n    \"Views\": [\"Models\"],\n    \"Database\": [\"Models\"]\n  }\n}\n",
  "layered": "// mapx:preset/layered: the classic layered (n-tier) architecture.\n// AR-15. Each layer may depend on the layer directly below it and on Common; nothing depends upward.\n// Parameter: root, the folder holding the layer folders (\"src/\" by default, \"\" for the repo root).\n{\n  \"parameters\": { \"root\": \"src/\" },\n  \"layers\": [\n    // What users and clients talk to: controllers, handlers, routes, views.\n    { \"name\": \"Presentation\", \"selectors\": [{ \"path\": \"%root%{presentation,controllers,controller,handlers,routes,api,web,ui,views}/**\" }] },\n    // The rules of the application: services and use cases.\n    { \"name\": \"Business\", \"selectors\": [{ \"path\": \"%root%{business,services,service,logic,usecases}/**\" }] },\n    // Data access: repositories, the database, DAOs.\n    { \"name\": \"Persistence\", \"selectors\": [{ \"path\": \"%root%{persistence,repositories,repository,data,dal,dao,db,database}/**\" }] },\n    // Helpers, types and constants every layer may use.\n    { \"name\": \"Common\", \"selectors\": [{ \"path\": \"%root%{common,shared,utils,util,lib,types,helpers}/**\" }] }\n  ],\n  \"rules\": {\n    \"Presentation\": [\"Business\", \"Common\"],\n    \"Business\": [\"Persistence\", \"Common\"],\n    \"Persistence\": [\"Common\"],\n    \"Common\": []\n  }\n}\n",
  "mvc": "// mapx:preset/mvc: Model-View-Controller.\n// AR-15 (M5-17-R1). Controllers take the input, update models and pick views; views read models;\n// models depend on nothing. A view never calls its controller.\n// Parameter: root, the folder holding the layer folders (\"src/\" by default, \"\" for the repo root).\n{\n  \"parameters\": { \"root\": \"src/\" },\n  \"layers\": [\n    // Controllers: input handling.\n    { \"name\": \"Controllers\", \"selectors\": [{ \"path\": \"%root%{controllers,controller}/**\" }] },\n    // Views and templates.\n    { \"name\": \"Views\", \"selectors\": [{ \"path\": \"%root%{views,view,templates}/**\" }] },\n    // Models: data and rules.\n    { \"name\": \"Models\", \"selectors\": [{ \"path\": \"%root%{models,model}/**\" }] }\n  ],\n  \"rules\": {\n    \"Controllers\": [\"Views\", \"Models\"],\n    \"Views\": [\"Models\"],\n    \"Models\": []\n  }\n}\n",
  "mvvm": "// mapx:preset/mvvm: Model-View-ViewModel.\n// AR-15 (M5-17-R1). Views bind to view models and read the models they expose; view models call\n// services; services load models; models depend on nothing. A view never calls a service.\n// Parameter: root, the folder holding the layer folders (\"src/\" by default, \"\" for the repo root).\n{\n  \"parameters\": { \"root\": \"src/\" },\n  \"layers\": [\n    // Views: screens, pages and their components.\n    { \"name\": \"Views\", \"selectors\": [{ \"path\": \"%root%{views,view,ui,screens,pages}/**\" }] },\n    // View models: presentation state and commands.\n    { \"name\": \"ViewModels\", \"selectors\": [{ \"path\": \"%root%{viewmodels,viewmodel,view-models,view_models,ViewModels}/**\" }] },\n    // Services and repositories behind the view models.\n    { \"name\": \"Services\", \"selectors\": [{ \"path\": \"%root%{services,repositories,data}/**\" }] },\n    // Models: data and rules.\n    { \"name\": \"Models\", \"selectors\": [{ \"path\": \"%root%{models,model,Models}/**\" }] }\n  ],\n  \"rules\": {\n    \"Views\": [\"ViewModels\", \"Models\"],\n    \"ViewModels\": [\"Services\", \"Models\"],\n    \"Services\": [\"Models\"],\n    \"Models\": []\n  }\n}\n",
  "nestjs": "// mapx:preset/nestjs: a NestJS application.\n// AR-15. By Nest's file-name conventions, the decorators MapX stores (M5-10) and the enhancer\n// interfaces (M5-17-R1): a class is placed by its decorator or interface wherever it lives, and the\n// file-name suffixes stay the fallback for classes without one.\n// Controllers reach the domain only through providers; entities depend on nothing.\n// No parameters: the file names place every file, wherever it is.\n{\n  \"layers\": [\n    // @Module classes: they wire controllers, providers and other modules.\n    { \"name\": \"Module\", \"selectors\": [{ \"path\": \"**/*.module.{ts,js}\" }, { \"decorator\": \"Module\", \"members\": true }] },\n    // @Controller classes: the HTTP surface.\n    { \"name\": \"Controller\", \"selectors\": [{ \"path\": \"**/*.controller.{ts,js}\" }, { \"decorator\": \"Controller\", \"members\": true }] },\n    // Guards, interceptors, pipes, filters, middleware and auth strategies, and any class that\n    // implements one of Nest's enhancer interfaces.\n    { \"name\": \"Enhancer\", \"selectors\": [\n      { \"path\": \"**/*.{guard,interceptor,pipe,filter,middleware,strategy}.{ts,js}\" },\n      { \"implements\": \"/^@nestjs\\\\/common#(CanActivate|NestInterceptor|PipeTransform|ExceptionFilter|NestMiddleware)$/\" }\n    ] },\n    // Services, providers and repositories, and any other @Injectable class: an enhancer is\n    // @Injectable too, and stays in Enhancer only.\n    { \"name\": \"Provider\", \"selectors\": [\n      { \"path\": \"**/*.{service,provider,repository}.{ts,js}\" },\n      { \"all\": [\n        { \"decorator\": \"Injectable\", \"members\": true },\n        { \"not\": { \"any\": [\n          { \"path\": \"**/*.{guard,interceptor,pipe,filter,middleware,strategy}.{ts,js}\" },\n          { \"implements\": \"/^@nestjs\\\\/common#(CanActivate|NestInterceptor|PipeTransform|ExceptionFilter|NestMiddleware)$/\" }\n        ] } }\n      ] }\n    ] },\n    // Data transfer objects.\n    { \"name\": \"Dto\", \"selectors\": [{ \"path\": \"**/*.dto.{ts,js}\" }, { \"path\": \"**/dto/**\" }] },\n    // Persistence entities, and any class decorated @Entity (TypeORM, MikroORM).\n    { \"name\": \"Entity\", \"selectors\": [{ \"path\": \"**/*.entity.{ts,js}\" }, { \"path\": \"**/entities/**\" }, { \"decorator\": \"Entity\", \"members\": true }] }\n  ],\n  \"rules\": {\n    \"Module\": [\"Controller\", \"Enhancer\", \"Provider\", \"Entity\"],\n    \"Controller\": [\"Enhancer\", \"Provider\", \"Dto\"],\n    \"Enhancer\": [\"Provider\", \"Dto\", \"Entity\"],\n    \"Provider\": [\"Dto\", \"Entity\"],\n    \"Dto\": [\"Entity\"],\n    \"Entity\": []\n  }\n}\n",
  "nextjs": "// mapx:preset/nextjs: a Next.js application (App Router or Pages Router).\n// AR-15 (M5-17-R1). By Next's routing folders and the usual shared folders, top-level or colocated\n// in app/ (the Next.js Learn layout: app/ui, app/lib). Route handlers (app/**/route.ts, pages/api/**)\n// and middleware are the HTTP surface; server actions (actions.ts files, actions/) are their own\n// layer, which pages and components may call; lib/ depends on nothing in the app.\n// Parameter: root, the folder holding app/ or pages/ (\"\" by default; \"src/\" with the src directory).\n{\n  \"parameters\": { \"root\": \"\" },\n  \"layers\": [\n    // Pages, layouts, loading and error states of app/ and pages/: the rest of app/ and pages/.\n    { \"name\": \"Routes\", \"selectors\": [{ \"all\": [\n      { \"path\": \"%root%{app,pages}/**\" },\n      { \"not\": { \"any\": [\n        { \"path\": \"%root%app/**/route.{ts,tsx,js,jsx}\" },\n        { \"path\": \"%root%pages/api/**\" },\n        { \"path\": \"%root%**/actions.{ts,tsx,js,jsx}\" },\n        { \"path\": \"%root%app/{_components,components,ui,_hooks,hooks,_lib,lib,utils}/**\" }\n      ] } }\n    ] }] },\n    // Route handlers, API routes and middleware: the HTTP surface.\n    { \"name\": \"Api\", \"selectors\": [\n      { \"path\": \"%root%app/**/route.{ts,tsx,js,jsx}\" },\n      { \"path\": \"%root%pages/api/**\" },\n      { \"path\": \"%root%middleware.{ts,js}\" }\n    ] },\n    // Server actions.\n    { \"name\": \"Actions\", \"selectors\": [{ \"path\": \"%root%**/actions.{ts,tsx,js,jsx}\" }, { \"path\": \"%root%actions/**\" }] },\n    // React components.\n    { \"name\": \"Components\", \"selectors\": [{ \"all\": [\n      { \"any\": [{ \"path\": \"%root%{components,ui}/**\" }, { \"path\": \"%root%app/{_components,components,ui}/**\" }] },\n      { \"not\": { \"path\": \"%root%**/actions.{ts,tsx,js,jsx}\" } }\n    ] }] },\n    // React hooks.\n    { \"name\": \"Hooks\", \"selectors\": [{ \"path\": \"%root%hooks/**\" }, { \"path\": \"%root%app/{_hooks,hooks}/**\" }] },\n    // Data access, utilities and types.\n    { \"name\": \"Lib\", \"selectors\": [{ \"all\": [\n      { \"any\": [{ \"path\": \"%root%{lib,utils,services,types}/**\" }, { \"path\": \"%root%app/{_lib,lib,utils}/**\" }] },\n      { \"not\": { \"path\": \"%root%**/actions.{ts,tsx,js,jsx}\" } }\n    ] }] }\n  ],\n  \"rules\": {\n    \"Routes\": [\"Components\", \"Hooks\", \"Actions\", \"Lib\"],\n    \"Api\": [\"Actions\", \"Lib\"],\n    \"Actions\": [\"Lib\"],\n    \"Components\": [\"Hooks\", \"Actions\", \"Lib\"],\n    \"Hooks\": [\"Actions\", \"Lib\"],\n    \"Lib\": []\n  }\n}\n",
  "onion": "// mapx:preset/onion: the Onion Architecture, rings depending inward only.\n// AR-15 (M5-17-R1). The domain model at the centre, then domain services, then application\n// services; the outer ring (presentation and infrastructure) depends inward and never on itself:\n// the two meet only at the composition root.\n// Parameter: root, the folder holding the ring folders (\"src/\" by default, \"\" for the repo root).\n{\n  \"parameters\": { \"root\": \"src/\" },\n  \"layers\": [\n    // The centre: entities, value objects and the repository interfaces.\n    { \"name\": \"DomainModel\", \"selectors\": [{ \"path\": \"%root%domain/{model,models,entities}/**\" }, { \"path\": \"%root%{core,domain-model}/**\" }] },\n    // Domain services: rules that span entities.\n    { \"name\": \"DomainServices\", \"selectors\": [{ \"path\": \"%root%domain/services/**\" }, { \"path\": \"%root%domain-services/**\" }] },\n    // Application services: the use cases.\n    { \"name\": \"ApplicationServices\", \"selectors\": [{ \"path\": \"%root%{application,application-services,app-services}/**\" }] },\n    // The outer ring, user side: UI, API, CLI.\n    { \"name\": \"Presentation\", \"selectors\": [{ \"path\": \"%root%{presentation,ui,api,web}/**\" }] },\n    // The outer ring, machine side: persistence and external services.\n    { \"name\": \"Infrastructure\", \"selectors\": [{ \"path\": \"%root%{infrastructure,infra,persistence}/**\" }] }\n  ],\n  \"rules\": {\n    \"Presentation\": [\"ApplicationServices\", \"DomainServices\", \"DomainModel\"],\n    \"Infrastructure\": [\"ApplicationServices\", \"DomainServices\", \"DomainModel\"],\n    \"ApplicationServices\": [\"DomainServices\", \"DomainModel\"],\n    \"DomainServices\": [\"DomainModel\"],\n    \"DomainModel\": []\n  }\n}\n",
  "rails": "// mapx:preset/rails: a Ruby on Rails application.\n// AR-15 (M5-17-R1). By Rails' app/ folders, and by the framework base classes wherever a class\n// lives: a subclass of ActiveRecord::Base (through ApplicationRecord), ActionController, ActiveJob,\n// ActionMailer or ActionCable is placed by its ancestry. Models may enqueue jobs and send mail from\n// their callbacks, and never depend on controllers or services.\n// Parameter: root, the folder holding the application (\"\" when the Gemfile is at the repo root).\n{\n  \"parameters\": { \"root\": \"\" },\n  \"layers\": [\n    // config/routes.rb: it names controllers by symbol.\n    { \"name\": \"Routes\", \"selectors\": [{ \"path\": \"%root%config/routes.rb\" }, { \"path\": \"%root%config/routes/**\" }] },\n    // Controllers: app/controllers, and any ActionController subclass.\n    { \"name\": \"Controllers\", \"selectors\": [\n      { \"path\": \"%root%app/controllers/**\" },\n      { \"inherits\": \"ActionController::Base\" },\n      { \"inherits\": \"ActionController::API\" }\n    ] },\n    // Action Cable channels.\n    { \"name\": \"Channels\", \"selectors\": [{ \"path\": \"%root%app/channels/**\" }, { \"inherits\": \"ActionCable::Channel::Base\" }] },\n    // View helpers.\n    { \"name\": \"Helpers\", \"selectors\": [{ \"path\": \"%root%app/helpers/**\" }] },\n    // Service objects, interactors and form objects outside the framework.\n    { \"name\": \"Services\", \"selectors\": [{ \"path\": \"%root%app/{services,interactors,operations,forms}/**\" }] },\n    // Active Job jobs.\n    { \"name\": \"Jobs\", \"selectors\": [{ \"path\": \"%root%app/jobs/**\" }, { \"inherits\": \"ActiveJob::Base\" }] },\n    // Action Mailer mailers.\n    { \"name\": \"Mailers\", \"selectors\": [{ \"path\": \"%root%app/mailers/**\" }, { \"inherits\": \"ActionMailer::Base\" }] },\n    // Active Record models (and concerns under app/models).\n    { \"name\": \"Models\", \"selectors\": [{ \"path\": \"%root%app/models/**\" }, { \"inherits\": \"ActiveRecord::Base\" }] },\n    // Migrations, the schema and seeds.\n    { \"name\": \"Database\", \"selectors\": [{ \"path\": \"%root%db/**\" }] }\n  ],\n  \"rules\": {\n    \"Routes\": [\"Controllers\"],\n    \"Controllers\": [\"Helpers\", \"Services\", \"Jobs\", \"Mailers\", \"Models\"],\n    \"Channels\": [\"Services\", \"Jobs\", \"Models\"],\n    \"Helpers\": [\"Models\"],\n    \"Services\": [\"Jobs\", \"Mailers\", \"Models\"],\n    \"Jobs\": [\"Services\", \"Mailers\", \"Models\"],\n    \"Mailers\": [\"Helpers\", \"Models\"],\n    \"Models\": [\"Jobs\", \"Mailers\"],\n    \"Database\": [\"Models\"]\n  }\n}\n",
  "spring": "// mapx:preset/spring: a Spring Boot application.\n// AR-15 (M5-17-R1). By Spring's stereotype annotations, which MapX stores as decorators, and by\n// Spring Data ancestry wherever a class lives; the package names stay the fallback for classes\n// without them. Controllers reach the repositories only through services, and may map entities to\n// DTOs; entities depend on nothing.\n// No parameters: the annotations and package names place every file, in whichever module it is.\n{\n  \"layers\": [\n    // @Controller and @RestController classes, and their advice: the HTTP surface.\n    { \"name\": \"Controller\", \"selectors\": [\n      { \"path\": \"**/{controller,controllers,web,rest}/**\" },\n      { \"decorator\": \"/^(Rest)?Controller(Advice)?$/\", \"members\": true }\n    ] },\n    // @Configuration classes: the application context's wiring.\n    { \"name\": \"Config\", \"selectors\": [{ \"path\": \"**/{config,configuration}/**\" }, { \"decorator\": \"Configuration\", \"members\": true }] },\n    // @Service classes: the use cases.\n    { \"name\": \"Service\", \"selectors\": [{ \"path\": \"**/{service,services}/**\" }, { \"decorator\": \"Service\", \"members\": true }] },\n    // @Repository classes and Spring Data repositories (any type extending one of its interfaces).\n    { \"name\": \"Repository\", \"selectors\": [\n      { \"path\": \"**/{repository,repositories}/**\" },\n      { \"decorator\": \"Repository\", \"members\": true },\n      { \"inherits\": \"/^org\\\\.springframework\\\\.data\\\\./\" }\n    ] },\n    // Request and response objects.\n    { \"name\": \"Dto\", \"selectors\": [{ \"path\": \"**/{dto,dtos}/**\" }] },\n    // JPA entities and embeddables.\n    { \"name\": \"Entity\", \"selectors\": [\n      { \"path\": \"**/{domain,entity,entities,model}/**\" },\n      { \"decorator\": \"/^(Entity|Embeddable|MappedSuperclass)$/\", \"members\": true }\n    ] }\n  ],\n  \"rules\": {\n    \"Controller\": [\"Service\", \"Dto\", \"Entity\"],\n    \"Config\": [\"Service\", \"Repository\"],\n    \"Service\": [\"Repository\", \"Entity\", \"Dto\"],\n    \"Repository\": [\"Entity\"],\n    \"Dto\": [\"Entity\"],\n    \"Entity\": []\n  }\n}\n",
  "symfony": "// mapx:preset/symfony: a Symfony application.\n// AR-15 (M5-17-R1). By the src/ folders of the Symfony skeleton, and by the framework's base types\n// and attributes wherever a class lives: AbstractController, AbstractType, Command and #[AsCommand],\n// EventSubscriberInterface and #[AsEventListener], #[AsMessageHandler], Doctrine's repositories and\n// #[ORM\\Entity]. An entity names its repository (`#[ORM\\Entity(repositoryClass: …)]`, as make:entity\n// writes it), and a form may query one (an EntityType's query_builder); entities depend on nothing\n// else, messages on nothing; only controllers use forms.\n// Parameter: root, the folder holding the application (\"\" when bin/console is at the repo root).\n{\n  \"parameters\": { \"root\": \"\" },\n  \"layers\": [\n    // Controllers.\n    { \"name\": \"Controller\", \"selectors\": [\n      { \"path\": \"%root%src/Controller/**\" },\n      { \"inherits\": \"Symfony\\\\Bundle\\\\FrameworkBundle\\\\Controller\\\\AbstractController\" }\n    ] },\n    // Form types.\n    { \"name\": \"Form\", \"selectors\": [{ \"path\": \"%root%src/Form/**\" }, { \"inherits\": \"Symfony\\\\Component\\\\Form\\\\AbstractType\" }] },\n    // Console commands.\n    { \"name\": \"Command\", \"selectors\": [\n      { \"path\": \"%root%src/Command/**\" },\n      { \"inherits\": \"Symfony\\\\Component\\\\Console\\\\Command\\\\Command\" },\n      { \"decorator\": \"Symfony\\\\Component\\\\Console\\\\Attribute\\\\AsCommand\", \"members\": true }\n    ] },\n    // Event subscribers and listeners.\n    { \"name\": \"EventSubscriber\", \"selectors\": [\n      { \"path\": \"%root%src/{EventSubscriber,EventListener}/**\" },\n      { \"implements\": \"Symfony\\\\Component\\\\EventDispatcher\\\\EventSubscriberInterface\" },\n      { \"decorator\": \"Symfony\\\\Component\\\\EventDispatcher\\\\Attribute\\\\AsEventListener\", \"members\": true }\n    ] },\n    // Messenger handlers.\n    { \"name\": \"MessageHandler\", \"selectors\": [\n      { \"path\": \"%root%src/MessageHandler/**\" },\n      { \"decorator\": \"Symfony\\\\Component\\\\Messenger\\\\Attribute\\\\AsMessageHandler\", \"members\": true }\n    ] },\n    // Messenger messages: plain data.\n    { \"name\": \"Message\", \"selectors\": [{ \"path\": \"%root%src/Message/**\" }] },\n    // Application services.\n    { \"name\": \"Service\", \"selectors\": [{ \"path\": \"%root%src/Service/**\" }] },\n    // Doctrine repositories.\n    { \"name\": \"Repository\", \"selectors\": [\n      { \"path\": \"%root%src/Repository/**\" },\n      { \"inherits\": \"Doctrine\\\\Bundle\\\\DoctrineBundle\\\\Repository\\\\ServiceEntityRepository\" },\n      { \"inherits\": \"Doctrine\\\\ORM\\\\EntityRepository\" }\n    ] },\n    // Doctrine entities and embeddables.\n    { \"name\": \"Entity\", \"selectors\": [\n      { \"path\": \"%root%src/Entity/**\" },\n      { \"decorator\": \"Doctrine\\\\ORM\\\\Mapping\\\\Entity\", \"members\": true },\n      { \"decorator\": \"Doctrine\\\\ORM\\\\Mapping\\\\Embeddable\", \"members\": true }\n    ] }\n  ],\n  \"rules\": {\n    \"Controller\": [\"Form\", \"Service\", \"Message\", \"Repository\", \"Entity\"],\n    \"Form\": [\"Repository\", \"Entity\"],\n    \"Command\": [\"Service\", \"Message\", \"Repository\", \"Entity\"],\n    \"EventSubscriber\": [\"Service\", \"Message\", \"Repository\", \"Entity\"],\n    \"MessageHandler\": [\"Service\", \"Message\", \"Repository\", \"Entity\"],\n    \"Service\": [\"Message\", \"Repository\", \"Entity\"],\n    \"Repository\": [\"Entity\"],\n    \"Message\": [],\n    \"Entity\": [\"Repository\"]\n  }\n}\n",
  "vue": "// mapx:preset/vue: a Vue 3 application (Vite or Vue CLI layout, Vue Router, Pinia or Vuex).\n// AR-15 (M5-17-R1). By the src/ folders of create-vue. Views compose components; components and\n// composables reach the API through stores; a navigation guard may read a store and a store may\n// navigate (router.push); the API client depends on nothing in the app but Shared.\n// Parameter: root, the folder holding the layer folders (\"src/\" by default, \"\" for the repo root).\n{\n  \"parameters\": { \"root\": \"src/\" },\n  \"layers\": [\n    // The entry point and the root component.\n    { \"name\": \"App\", \"selectors\": [{ \"path\": \"%root%{main.{ts,js},App.vue}\" }] },\n    // Route definitions and navigation guards.\n    { \"name\": \"Router\", \"selectors\": [{ \"path\": \"%root%router/**\" }] },\n    // Route-level components.\n    { \"name\": \"Views\", \"selectors\": [{ \"path\": \"%root%{views,pages}/**\" }] },\n    // Reusable components.\n    { \"name\": \"Components\", \"selectors\": [{ \"path\": \"%root%components/**\" }] },\n    // Composition functions.\n    { \"name\": \"Composables\", \"selectors\": [{ \"path\": \"%root%{composables,hooks}/**\" }] },\n    // Pinia or Vuex stores.\n    { \"name\": \"Stores\", \"selectors\": [{ \"path\": \"%root%{stores,store}/**\" }] },\n    // API clients and other services.\n    { \"name\": \"Services\", \"selectors\": [{ \"path\": \"%root%{services,api}/**\" }] },\n    // Types, utilities and constants every layer may use.\n    { \"name\": \"Shared\", \"selectors\": [{ \"path\": \"%root%{types,utils,lib,helpers,constants}/**\" }] }\n  ],\n  \"rules\": {\n    \"App\": [\"Router\", \"Views\", \"Components\", \"Stores\", \"Shared\"],\n    \"Router\": [\"Views\", \"Stores\", \"Shared\"],\n    \"Views\": [\"Components\", \"Composables\", \"Stores\", \"Services\", \"Shared\"],\n    \"Components\": [\"Composables\", \"Stores\", \"Shared\"],\n    \"Composables\": [\"Stores\", \"Services\", \"Shared\"],\n    \"Stores\": [\"Router\", \"Services\", \"Shared\"],\n    \"Services\": [\"Shared\"],\n    \"Shared\": []\n  }\n}\n",
};
